// Confere a assinatura do Leadtogo (X-Leadtogo-Assinatura: t=<unix>,v1=<hex>[,v1=<hex>]).
// Exige NODE_FUNCTION_ALLOW_BUILTIN=crypto no n8n. O segredo (whsec_...) é o mostrado ao cadastrar o webhook.
const crypto = require('crypto');
const SEGREDO = 'whsec_COLE_AQUI_O_SEGREDO_DO_WEBHOOK';
const TOLERANCIA_S = 300;

const item = $input.first();
const cab = item.json.headers || {};
const assinatura = String(cab['x-leadtogo-assinatura'] || '');
// Corpo bruto (opção "Raw Body" do nó Webhook); sem ela, o JSON recebido serializado de novo dá o mesmo texto
const bruto = item.binary && item.binary.data
  ? Buffer.from(item.binary.data.data, 'base64').toString('utf8')
  : JSON.stringify(item.json.body);

const t = Number((/(?:^|,)t=(\d+)/.exec(assinatura) || [])[1] || 0);
const recebidas = [...assinatura.matchAll(/v1=([0-9a-f]{64})/g)].map((m) => m[1]);
const esperada = crypto.createHmac('sha256', SEGREDO).update(`${t}.${bruto}`, 'utf8').digest('hex');
const noPrazo = Math.abs(Date.now() / 1000 - t) <= TOLERANCIA_S;
const confere = recebidas.some((r) =>
  crypto.timingSafeEqual(Buffer.from(r, 'hex'), Buffer.from(esperada, 'hex')),
);
const evento = JSON.parse(bruto);
return [{ json: { valido: noPrazo && confere, evento, entrega: cab['x-leadtogo-entrega'] || null } }];
